// Extract JSON from AI Assistant response
try {
  const response = items[0].json;
  const textContent = response.text || response.output || '';

  // Find JSON block in ```json ... ``` format
  const jsonMatch = textContent.match(/```json\n?([\s\S]*?)\n?```/);

  let extractedAction = null;

  if (jsonMatch && jsonMatch[1]) {
    try {
      extractedAction = JSON.parse(jsonMatch[1]);
    } catch (e) {
      console.log('JSON Parse Error:', e.message);
      extractedAction = null;
    }
  }

  return [{
    json: {
      ...items[0].json,
      extracted_action: extractedAction,
      full_response: textContent,
      has_valid_action: extractedAction && extractedAction.action ? true : false
    }
  }];

} catch (error) {
  return [{
    json: {
      ...items[0].json,
      extracted_action: null,
      error: error.message
    }
  }];
}
